package com.lebzlon.measurementtracker.entity;
import jakarta.persistence.*; import java.time.Instant; import java.util.*;
@Entity @Table(name="meters",uniqueConstraints=@UniqueConstraint(columnNames={"serialNumber"}))
public class Meter { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,unique=true) private String serialNumber; @Enumerated(EnumType.STRING) @Column(nullable=false) private MeterType type; private String title; @Column(nullable=false) private boolean active=true; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(nullable=false) private User user; @Column(nullable=false) private Instant createdAt=Instant.now(); @OneToMany(mappedBy="meter") private List<MeterReading> readings=new ArrayList<>();
public Long getId(){return id;} public String getSerialNumber(){return serialNumber;} public void setSerialNumber(String s){this.serialNumber=s;} public MeterType getType(){return type;} public void setType(MeterType t){this.type=t;} public String getTitle(){return title;} public void setTitle(String t){this.title=t;} public boolean isActive(){return active;} public void setActive(boolean a){this.active=a;} public User getUser(){return user;} public void setUser(User u){this.user=u;} }
